import {mkdir,writeFile,readFile,rm,cp} from 'node:fs/promises';
import path from 'node:path';
import {toolDepthHtml,hubDepthHtml,articleDepthHtml} from './content-depth.mjs';

const root=process.cwd(), out=path.join(root,'site');
const managedBadgePattern=/<div style="width: 100%;max-width: 1200px;margin-inline: auto;padding: 2rem 0;text-align:center;"><a href="https:\/\/boostdomainrating\.com\/item\/guitarsetuplab\.com\?utm_source=badge"[\s\S]*?<\/div>/;
const deployedHomeBeforeBuild=await readFile(path.join(root,'index.html'),'utf8');
const userManagedHomeBadge=deployedHomeBeforeBuild.match(managedBadgePattern)?.[0]||'';
await rm(out,{recursive:true,force:true});
for(const d of ['assets','tools','guides','reference','comparisons','categories']) await mkdir(path.join(out,d),{recursive:true});
for(const f of ['style.css','narrow.css','geometry.css','print.css','calculations.js','pickup-fit.js','app.js']) await writeFile(path.join(out,'assets',f),await (await import('node:fs/promises')).readFile(path.join(root,'scripts','assets',f),'utf8'));
await cp(path.join(root,'scripts','assets','geometry'),path.join(out,'assets','geometry'),{recursive:true});

