const home=`<section class="home-hero"><div><p class="eyebrow">Setup, Repair & Luthier Tools</p><h1>Turn guitar symptoms into a measured work order.</h1><p class="lede">A safety-first bench for diagnosing playability, comparing measurements, planning reversible adjustments, and printing a record of the result.</p><div class="actions"><a class="button" href="/tools/guitar-setup-wizard.html">Start setup triage</a><a class="button secondary" href="/categories/measurement.html">Open measurement tools</a></div></div><aside class="ticket"><b>BENCH SEQUENCE / 01</b><ol><li>Listen & locate</li><li>Measure current state</li><li>Change one variable</li><li>Retune & verify</li><li>Record the result</li></ol></aside></section><section><p class="eyebrow">Four connected benches</p><h2>Do the next useful check—not every adjustment at once.</h2><div class="card-grid"><a class="card featured" href="/categories/diagnostics.html"><small>01 / Diagnose</small><strong>Locate the system</strong><span>Separate string, nut, relief, action, fret, bridge, and climate clues.</span></a><a class="card" href="/categories/measurement.html"><small>02 / Measure</small><strong>Build a baseline</strong><span>Convert and interpret relief, action, scale, gauge, and pickup clearance.</span></a><a class="card" href="/categories/electronics.html"><small>03 / Electronics</small><strong>Isolate signal problems</strong><span>Separate cable, environment, switching, pickup, and control-load clues.</span></a><a class="card" href="/categories/documents.html"><small>04 / Record</small><strong>Print the evidence</strong><span>Create shop-ready intake, quote, job, measurement, and condition records.</span></a></div></section><section class="bench"><div><p class="eyebrow">Popular starting points</p><h2>What is the instrument telling you?</h2></div><div class="list">${tools.slice(1,7).map(t=>`<a href="/tools/${t.slug}.html"><span>${t.title}</span><i>Open →</i></a>`).join('')}</div></section><section class="bench"><div><p class="eyebrow">Bench library</p><h2>Methods, terms, and decision references.</h2></div><div class="list"><a href="/guides/setup-order.html"><span>Safe setup order</span><i>Guide →</i></a><a href="/guides/measure-neck-relief.html"><span>Measure neck relief</span><i>Guide →</i></a><a href="/guides/used-guitar-inspection.html"><span>Used-guitar inspection</span><i>Guide →</i></a><a href="/guides/document-guitar-setup.html"><span>Document a setup</span><i>Guide →</i></a><a href="/guides/diagnose-guitar-hum-safely.html"><span>Diagnose hum safely</span><i>Guide →</i></a><a href="/guides/repair-intake-workflow.html"><span>Repair intake workflow</span><i>Guide →</i></a><a href="/guides/choosing-pot-capacitor-values.html"><span>Choose pot and capacitor values</span><i>Guide →</i></a><a href="/guides/string-gauge-setup-effects.html"><span>Gauge-change setup effects</span><i>Guide →</i></a><a href="/reference/unit-conversion.html"><span>Unit conversion</span><i>Reference →</i></a><a href="/reference/measurement-points.html"><span>Measurement points</span><i>Reference →</i></a><a href="/reference/string-tension-formula.html"><span>String tension formula</span><i>Reference →</i></a><a href="/reference/pickup-wiring-terms.html"><span>Pickup wiring terms</span><i>Reference →</i></a><a href="/comparisons/pot-values.html"><span>250k vs 500k vs 1M pots</span><i>Compare →</i></a><a href="/comparisons/series-parallel-coil-split.html"><span>Series vs parallel vs coil split</span><i>Compare →</i></a></div></section>`;
const expandedHome=home.replace('Four connected benches','Five connected benches').replace('<section class="bench"><div><p class="eyebrow">Popular starting points</p>',`<section class="bench"><div><p class="eyebrow">05 / Build</p><h2>Plan instrument geometry before marking material.</h2><p>Calculate fret coordinates, spacing, radii, multiscale layouts, angles, tremolo balance, and shim taper from named physical datums.</p></div><div class="list"><a href="/categories/luthier.html"><span>Open the luthier geometry bench</span><i>11 tools →</i></a><a href="/guides/print-actual-size.html"><span>Print templates at actual size</span><i>Guide →</i></a><a href="/reference/geometry-measurement.html"><span>Geometry measurement definitions</span><i>Reference →</i></a></div></section><section class="bench"><div><p class="eyebrow">Popular starting points</p>`);
const expandedHomeWithFit=expandedHome.replace('Five connected benches','Six connected benches').replace('<section class="bench"><div><p class="eyebrow">Popular starting points</p>',`<section class="bench"><div><p class="eyebrow">06 / Fit</p><h2>Measure pickup compatibility before ordering or altering an instrument.</h2><p>Project string spread and compare pole, cavity, ring, and mounting dimensions with current manufacturer drawings.</p></div><div class="list"><a href="/categories/fit.html"><span>Open the pickup fit bench</span><i>4 tools →</i></a><a href="/guides/measure-pickup-fit.html"><span>Measure pickup fit</span><i>Guide →</i></a><a href="/reference/pickup-dimensions.html"><span>Pickup dimension definitions</span><i>Reference →</i></a></div></section><section class="bench"><div><p class="eyebrow">Popular starting points</p>`);
await writeFile(path.join(out,'index.html'),page({title:'Guitar Setup, Repair & Luthier Tools',description:'Interactive guitar setup diagnostics, measurement helpers, checklists, printable records, and luthier geometry planners.',body:expandedHomeWithFit}));
{
 const file=path.join(out,'index.html'),html=await readFile(file,'utf8');
 const depth=`<article class="prose home-depth"><h2>A measured path from symptom to record</h2><p>Guitar Setup Lab is organized around dependencies. Stable strings and intended tuning come before relief; relief comes before bridge action; pickup clearance follows the string path; intonation is checked only after the earlier geometry is stable. Electronics begins with a safe cable and environment substitution, while build geometry begins with named datums and calibrated transfer.</p><h2>Choose one unresolved question</h2><p>Use Diagnose when the cause is unknown, Measure when a datum needs conversion or comparison, Electronics when signal behavior can be isolated safely, Record when shop evidence or permission must be preserved, and Build when coordinates or angles must be tested before material is marked. Each tool links to only the next related decisions so an isolated symptom does not become an unnecessary complete overhaul.</p><h2>Evidence over targets</h2><p>The site does not publish one action, relief, pickup height, nut margin, or neck angle as correct for every instrument. Record the instrument, strings, tuning, position, fret, unit, tool resolution, climate when relevant, and the player’s actual symptom. Repeat the measurement, change one reversible variable, retune, and repeat the same test.</p><h2>Boundaries</h2><p>No browser can feel truss-rod resistance, inspect a joint, authenticate a used instrument, model every pickup circuit, or verify that a printer transferred a template at physical size. Stop for conflicting readings, abnormal force, structural movement, electrical sensation, heat, odor, or an irreversible step whose cause is not confirmed. Use manufacturer documentation and a qualified technician where the instrument or powered equipment requires direct inspection.</p></article>`;
 await writeFile(file,html.replace('</main>',`${depth}</main>`));
}

const basics={
 'about.html':['About Guitar Setup Lab','Why this site treats setup as a measured workflow.',`<section class="page-head"><p class="eyebrow">About the bench</p><h1>About Guitar Setup Lab</h1><p class="lede">We build independent, browser-based tools for players, repair shops, and instrument makers.</p></section><section class="prose"><h2>Our method</h2><p>Setup is a chain of observations. A symptom leads to a measurement; a measurement supports a reversible plan; the result is checked and recorded. The tools here make that chain visible.</p><h2>Safety boundary</h2><p>No browser tool can inspect an instrument. We avoid guaranteed diagnoses, automatic instructions for irreversible work, high-voltage amplifier repair, and exact truss-rod turns. When evidence conflicts, stop and consult a qualified technician.</p><h2>Editorial approach</h2><p>Reference values are labeled as comparison points. Manufacturer procedures and primary technical sources are preferred. Contact: <a href="mailto:canghun13@naver.com">canghun13@naver.com</a>.</p></section>`],
 'contact.html':['Contact','Contact Guitar Setup Lab about tool corrections or accessibility.',`<section class="page-head"><p class="eyebrow">Bench notes</p><h1>Contact</h1><p class="lede">Found a calculation, wording, or accessibility issue? Send the instrument type, page URL, input values, and observed result.</p></section><section class="prose"><h2>Email</h2><p><a class="button" href="mailto:canghun13@naver.com">canghun13@naver.com</a></p><p>Do not send urgent electrical or structural repair requests. A website cannot inspect an instrument or replace an in-person technician.</p></section>`],
 'privacy.html':['Privacy','Privacy details for Guitar Setup Lab and its browser-based tools.',`<section class="page-head"><p class="eyebrow">Policy</p><h1>Privacy</h1><p class="lede">Tool inputs are processed in your browser and are not submitted to our server.</p></section><section class="prose"><h2>Analytics</h2><p>We use Google Analytics 4 to understand aggregate page use. Google may process device, browser, and interaction data according to its policies. This site does not require an account.</p><h2>Local actions</h2><p>Copy and print actions use your browser. Avoid entering sensitive personal data into shop notes on a shared device.</p><h2>Contact</h2><p>Privacy questions: <a href="mailto:canghun13@naver.com">canghun13@naver.com</a>.</p></section>`],
 '404.html':['Page not found','The requested Guitar Setup Lab page could not be found.',`<section class="page-head"><p class="eyebrow">404 / misplaced bench ticket</p><h1>That page is not on this bench.</h1><p class="lede">The address may have changed. Return to the tool index and start from the symptom or measurement.</p><a class="button" href="/">Return home</a></section>`]
};
for(const [file,[title,description,body]] of Object.entries(basics)) await writeFile(path.join(out,file),page({title,description,slug:file,body}));

const guides=[
 ['setup-order','Safe Guitar Setup Order','Why tuning, relief, action, pickup clearance, and intonation should be checked in sequence.',`<h2>A controlled sequence</h2><ol><li>Install or assess stable strings and tune to the intended pitch.</li><li>Inspect structure, hardware, and climate clues.</li><li>Measure neck relief before judging bridge action.</li><li>Measure action on both sides and test the full fretboard.</li><li>Check pickup clearance while fretting the last fret.</li><li>Set intonation last, with a capable tuner.</li></ol><p>Retune after every change. Change one variable at a time so the outcome remains attributable.</p>`],
 ['measure-neck-relief','How to Measure Neck Relief','A repeatable capo, last-fret, and feeler-gauge method for recording relief.',`<h2>Measurement method</h2><ol><li>Tune the instrument and hold it in playing position.</li><li>Capo the first fret.</li><li>Hold the string at the last fret or neck/body joint.</li><li>Measure the gap near the middle of the span with a feeler gauge.</li></ol><p>Record where you measured and which string you used. A value alone does not prove that the truss rod should be adjusted.</p>`],
 ['used-guitar-inspection','Used Guitar Inspection Guide','Inspect structure, neck, frets, hardware, electronics, and playability before purchase.',`<h2>Bring evidence, not optimism</h2><p>Use a tuner, short cable, clean amplifier, flashlight, straightedge or ruler, and permission before adjusting anything. Verify serial and ownership claims separately.</p><h2>Walk the instrument</h2><p>Start with structure and repairs, then neck and truss-rod access, frets, hardware, electronics, acoustic noise, amplified signal, and setup measurements. Price uncertainty into the decision; do not treat the report as a warranty.</p>`],
 ['document-guitar-setup','How to Document a Guitar Setup','Create a useful before/after record with repeatable measurement points and test conditions.',`<h2>Record the baseline</h2><p>Name the instrument, tuning, string set, climate, measurement fret, and playing position. A number without its method is difficult to repeat.</p><h2>Separate observation from work</h2><p>Write the customer symptom, technician observation, measurements, work performed, and final test as separate sections. Record one-variable changes and include unresolved limits rather than promising an outcome.</p><p><a href="/tools/setup-measurement-sheet.html">Open the measurement sheet</a> or <a href="/tools/before-after-setup-card.html">create a before/after card</a>.</p>`],
 ['diagnose-guitar-hum-safely','How to Diagnose Guitar Hum Safely','Isolate guitar noise with substitution tests while staying outside amplifiers and mains equipment.',`<h2>Work from outside inward</h2><ol><li>Turn down monitoring level before changing connections.</li><li>Test one known-good cable directly into a known-safe amplifier or interface.</li><li>Compare another instrument, room, and power circuit.</li><li>Observe pickup-position, control, and touch behavior.</li><li>Document recent wiring or jack symptoms.</li></ol><p>Do not open an amplifier, power supply, or mains device. Stop for shocks, heat, odor, damaged power cables, or intermittent mains behavior.</p><p><a href="/tools/ground-hum-diagnostic.html">Run the Ground Hum Diagnostic</a>.</p>`],
 ['repair-intake-workflow','Guitar Repair Intake Workflow','Capture customer language, instrument identity, included items, permissions, and an initial condition baseline.',`<h2>Keep three voices separate</h2><p>The customer report describes what they experienced. The intake observation records visible facts. The diagnosis is created only after authorized inspection. Keeping these sections separate prevents assumptions from becoming shop history.</p><h2>Close the loop</h2><p>Tag included accessories, confirm communication and budget preferences, issue a job number, and connect approved work to a quote and job sheet. The intake record is a practical workflow document, not a liability waiver.</p>`],
 ['choosing-pot-capacitor-values','Choosing Guitar Pot and Capacitor Values','Compare pickup loading and tone-control ranges without promising an exact sound.',`<h2>Pot value changes loading</h2><p>For passive pickups, a higher resistance usually loads the pickup less and tends to preserve more high-frequency response. Cable capacitance, pickup inductance, control taper, wiring, and amplifier input all shape the result.</p><h2>Capacitor value changes the roll-off range</h2><p>A larger tone capacitor generally permits a darker fully-rolled-off sound. A simple RC cutoff is only a reference because a guitar pickup is not an ideal voltage source.</p><p>Compare <a href="/tools/potentiometer-value-selector.html">pot ranges</a>, <a href="/tools/tone-capacitor-comparison.html">capacitor values</a>, or the <a href="/comparisons/pot-values.html">250k/500k/1M decision guide</a>.</p>`],
 ['string-gauge-setup-effects','String Gauge Changes and Setup Effects','Plan gauge or tuning changes around published tension data and follow-up setup checks.',`<h2>Tension is not gauge alone</h2><p>Unit weight, vibrating length, and frequency determine tension. Two equal-diameter strings with different construction can have different unit weights.</p><h2>Recheck the system</h2><p>After a meaningful tension change, stabilize tuning and recheck relief, tremolo balance, nut movement, action, and intonation in that order. Do not cut a nut slot from a calculator result.</p><p><a href="/tools/string-tension-matcher.html">Compare supported tensions</a> and then use the <a href="/tools/string-gauge-change-planner.html">gauge-change planner</a>.</p>`],
 ['print-actual-size','How to Print Guitar Templates at Actual Size','Create and verify A4 or Letter PDFs without silently scaling a physical template.',`<h2>Export deliberately</h2><ol><li>Select the intended paper and orientation in the tool.</li><li>Print or save the result at 100% / Actual size.</li><li>Disable Fit, Shrink oversized pages, and printer-driver scaling.</li><li>Measure both the 50 mm and 2 inch calibration bars.</li><li>For tiled output, align overlap registration before trusting fret marks.</li></ol><p>A PDF with the correct page box can still be scaled by a viewer or printer. Reprint if either calibration bar is outside the selected tolerance.</p><p>Start with the <a href="/tools/fret-slot-print-template.html">Fret Slot Print Template</a> or <a href="/tools/fret-position-template.html">Fret Position Template</a>.</p>`],
 ['measure-string-spacing','How to Measure Nut and Bridge String Spacing','Measure centers, edge gaps, gauges, and margins without mixing definitions.',`<h2>Name the distance first</h2><p>Center spacing runs from one string centerline to the next. Edge gap runs from the side of one string to the side of the next. Overall spread runs between the outer string centers; physical margins run from a part edge to a string edge or center.</p><h2>Record real diameters</h2><p>Measure or obtain the installed gauges, keep all values in one unit, and state whether the outside margin is to the outer string center or edge. Equal-center and equal-edge-gap layouts answer different questions.</p><p>Compare the <a href="/tools/nut-string-spacing.html">nut</a> and <a href="/tools/bridge-string-spacing.html">bridge</a> planners before transferring marks.</p>`],
 ['measure-pickup-fit','How to Measure Pickup Fit','Measure the string path, pickup body, cavity, ring opening, and screw centers without mixing their datums.',`<h2>Measure the installed path first</h2><ol><li>Tune the guitar and measure outer-string centers at the nut and bridge witness points.</li><li>Measure from the nut witness point to the intended pickup center along the scale direction.</li><li>Remove hardware only with permission and record the cavity's smallest clear length, width, and usable depth.</li><li>Measure the candidate body, tabs, cover, wire exit, ring opening, and screw centers from its current manufacturer drawing.</li></ol><h2>Keep envelopes separate</h2><p>A pickup body can pass through a ring but still collide at its tabs, lead, springs, or cavity corner. A pole-spacing match does not prove that the cover, baseplate, ring, screw pattern, wiring, or installed height fits.</p><p>Start with the <a href="/tools/string-spread-at-pickup.html">string-spread projector</a>, then check <a href="/tools/pickup-pole-spacing-matcher.html">pole spacing</a>, <a href="/tools/pickup-route-clearance-checker.html">route clearance</a>, and <a href="/tools/pickup-ring-mount-fit.html">ring and mount geometry</a>.</p>`]
];
for(const [slug,title,description,content] of guides) await writeFile(path.join(out,'guides',`${slug}.html`),page({title,description,slug:`guides/${slug}.html`,body:`<section class="page-head"><p class="eyebrow">Field guide</p><h1>${title}</h1><p class="lede">${description}</p></section><article class="prose">${content}<div class="warning"><strong>Safety boundary</strong> Stop for abnormal resistance, cracking sounds, visible movement, electrical hazards, or measurements you cannot reproduce.</div></article>`,type:'Article'}));
for(const [slug,title,description] of guides){const file=path.join(out,'guides',`${slug}.html`),html=await readFile(file,'utf8');await writeFile(file,html.replace('</article>',`${articleDepthHtml(title,description,'guide',slug)}</article>`));}
const refs=[
 ['unit-conversion','Guitar Setup Unit Conversion Reference','Convert common millimetre and inch measurements used at the bench.',`<table><thead><tr><th>Millimetres</th><th>Decimal inches</th><th>Nearby fraction</th></tr></thead><tbody><tr><td>0.10</td><td>0.0039</td><td>≈ 1/256</td></tr><tr><td>0.20</td><td>0.0079</td><td>≈ 1/128</td></tr><tr><td>1.00</td><td>0.0394</td><td>≈ 5/128</td></tr><tr><td>1.50</td><td>0.0591</td><td>≈ 1/16</td></tr><tr><td>2.00</td><td>0.0787</td><td>≈ 5/64</td></tr></tbody></table><p>Fractions are rounded display aids. Use decimal millimetres or inches for calculations.</p>`],
 ['measurement-points','Guitar Setup Measurement Points','A reference for recording where and how each setup measurement was taken.',`<dl><dt>Relief</dt><dd>Gap near mid-span while the string is held at the first and last fret/body joint.</dd><dt>Action</dt><dd>Gap from fret crown to string underside at a named fret.</dd><dt>Pickup clearance</dt><dd>Gap from pole/top to string underside while fretting the last fret.</dd><dt>Scale</dt><dd>Twice nut-to-12th-fret is the nominal scale; saddle positions include compensation.</dd></dl>`],
 ['string-tension-formula','Guitar String Tension Formula Reference','Understand unit weight, scale length, frequency, units, and the supported data boundary.',`<h2>Published formula</h2><p><code>T = UW × (2 × L × F)² ÷ 386.4</code>, where T is pounds-force, UW is pounds per linear inch, L is scale length in inches, and F is frequency in hertz.</p><p>The matcher uses a limited subset of D’Addario XL published unit weights. It does not infer unit weight from diameter and does not claim that another brand or construction has the same tension.</p><h2>Working limits</h2><p>Scale is the vibrating length. Tuning frequency must match the intended octave. Results use ideal-string reference data; installation, construction tolerance, speaking length, and measurement conditions introduce differences.</p>`],
 ['pickup-wiring-terms','Pickup Wiring Terms Reference','Plain-language definitions for conductors, series, parallel, split, phase, ground, shielding, and switch poles.',`<dl><dt>Conductor</dt><dd>An insulated wire carrying a coil connection. A shield or ground braid is not automatically an independent coil conductor.</dd><dt>Series</dt><dd>Coils connected end-to-end; usually the fullest, highest-output humbucker mode.</dd><dt>Parallel</dt><dd>Both coils remain active in a lower-output, clearer arrangement that can retain hum canceling when wired correctly.</dd><dt>Coil split</dt><dd>One coil is bypassed. It is not the same as parallel and usually does not retain full hum canceling.</dd><dt>Electrical phase</dt><dd>Relative signal polarity. Thin combined sound can be a phase clue, but height and output mismatch must also be checked.</dd><dt>Shield</dt><dd>A conductive enclosure tied to the circuit reference. Shielding does not fix every ground or environmental noise problem.</dd></dl>`],
 ['fret-position-formula','Fret Position Formula Reference','Define cumulative 12-TET fret coordinates, adjacent spacing, scale length, and compensation boundaries.',`<h2>Equal-tempered coordinate</h2><p><code>d = s - s / 2^(n/12)</code>, where <code>s</code> is nominal scale length, <code>n</code> is fret number, and <code>d</code> is the distance from the nut witness point to that fret.</p><p>At fret 12, <code>d = s/2</code>. Adjacent slot spacing is the current cumulative coordinate minus the previous coordinate. Saddle compensation changes the practical string endpoint; it does not change the nominal fret formula.</p><p><a href="/tools/fret-position-template.html">Generate a coordinate table</a> or <a href="/tools/multiscale-fretboard-planner.html">plan per-string coordinates</a>.</p>`],
 ['geometry-measurement','Luthier Geometry Measurement Definitions','Define chord, sagitta, spread, datum, projection, break angle, and calibration measurements.',`<dl><dt>Datum / witness point</dt><dd>The physical reference actually touched by the string, fret, straightedge, or measuring tool.</dd><dt>Chord and sagitta</dt><dd>Chord is the straight endpoint-to-endpoint width; sagitta is the perpendicular center depth to the arc.</dd><dt>Spread</dt><dd>An overall center-to-center distance unless a tool explicitly says edge-to-edge.</dd><dt>Projection distance</dt><dd>The horizontal run used with a measured rise to calculate an angle.</dd><dt>Break angle</dt><dd>The side-view angle between the string segment and the reference plane at a witness point.</dd><dt>Calibration</dt><dd>A comparison between a commanded printed length and its physical measured length.</dd></dl><p>Never mix inches and millimetres inside one entry list. Repeat measurements and preserve the raw values before rounding.</p>`],
 ['pickup-dimensions','Pickup Fit Measurement Reference','Define string spread, pole spread, pickup body, route, ring opening, and mounting-center dimensions.',`<dl><dt>String spread</dt><dd>Center of the outer bass string to center of the outer treble string at the named pickup location.</dd><dt>Pole spread</dt><dd>Center of the first pole to center of the last pole; do not substitute bobbin or cover width.</dd><dt>Pickup body</dt><dd>The candidate's enclosing length, width, and installed depth. Record tabs, screws, lead exits, and protrusions separately.</dd><dt>Route clearance</dt><dd>The smallest usable cavity envelope after excluding curved corners, finish, shielding, wires, springs, and hardware.</dd><dt>Ring opening</dt><dd>The clear pass-through opening, not the ring's outside footprint.</dd><dt>Screw-center span</dt><dd>Center-to-center distance between corresponding mounting holes in each axis.</dd></dl><p>Use the current maker drawing for the exact model and measure the real guitar. Names such as standard, F-spaced, Trembucker, mini, or soapbar do not guarantee every external or mounting dimension.</p><p><a href="/guides/measure-pickup-fit.html">Follow the measurement guide</a> before using the fit tools.</p>`]
];
