const comparisons=[
 ['pot-values','250k vs 500k vs 1M Guitar Pots','Choose a passive guitar pot range by pickup loading, brightness goal, cable context, and control layout.',`<table><thead><tr><th>Nominal value</th><th>Typical starting context</th><th>General loading trend</th></tr></thead><tbody><tr><td>250kΩ</td><td>Many passive single-coils</td><td>More loading; often a warmer result</td></tr><tr><td>500kΩ</td><td>Many passive humbuckers and mixed designs</td><td>Less loading; often more high-frequency response</td></tr><tr><td>1MΩ</td><td>Special brightness or vintage-specific designs</td><td>Very light loading; can expose harshness/noise</td></tr></tbody></table><h2>Choose by the whole load</h2><p>These are common starting ranges, not compatibility rules. Pickup inductance/resistance, cable capacitance, amplifier input, tone network, pot tolerance, and control wiring all matter. Active systems often use manufacturer-specified lower values.</p><p><a href="/tools/potentiometer-value-selector.html">Use the selector</a> before purchasing parts.</p>`],
 ['series-parallel-coil-split','Series vs Parallel vs Coil Split','Compare availability, relative output, clarity, and noise-canceling tradeoffs for four-conductor humbuckers.',`<table><thead><tr><th>Mode</th><th>Relative tendency</th><th>Hum canceling</th><th>Requirement</th></tr></thead><tbody><tr><td>Series</td><td>Fullest / highest output</td><td>Usually retained</td><td>Standard humbucker connection</td></tr><tr><td>Parallel</td><td>Clearer / lower output</td><td>Can be retained</td><td>Independent coil starts/finishes and suitable switch</td></tr><tr><td>Coil split</td><td>Lower output / single-coil-like</td><td>Usually lost</td><td>Accessible series link and suitable switch</td></tr></tbody></table><p>Exact level and tone depend on the pickup and circuit. Manufacturer color codes are not universal. Record every connection before soldering.</p><p><a href="/tools/series-parallel-coil-split-selector.html">Check your available options</a>.</p>`],
 ['equal-center-vs-equal-gap','Equal-Center vs Equal-Edge-Gap String Spacing','Compare the visual, tactile, and measurement consequences of two string-spacing methods.',`<table><thead><tr><th>Method</th><th>What stays equal</th><th>Result with mixed gauges</th></tr></thead><tbody><tr><td>Equal center</td><td>Distance between every adjacent centerline</td><td>Visible edge gaps become smaller beside heavier strings.</td></tr><tr><td>Equal edge gap</td><td>Open space between adjacent string edges</td><td>Center distances grow where neighboring strings are heavier.</td></tr></tbody></table><p>Neither method supplies a universal margin or ergonomic target. Nut width, outer-string position, fret bevel, playing style, and real gauges remain design inputs.</p><p>Run both modes in the <a href="/tools/nut-string-spacing.html">Nut String Spacing Generator</a> before marking a blank.</p>`]
];
for(const [slug,title,description,content] of comparisons) await writeFile(path.join(out,'comparisons',`${slug}.html`),page({title,description,slug:`comparisons/${slug}.html`,body:`<section class="page-head"><p class="eyebrow">Decision comparison</p><h1>${title}</h1><p class="lede">${description}</p></section><article class="prose">${content}</article>`,type:'Article'}));
